static void mdev_device_release ( struct device * dev ) { struct mdev_device * mdev = to_mdev_device ( dev ) ; struct mdev_parent * parent = mdev -> type -> parent ; mutex_lock ( & mdev_list_lock ) ; list_del ( & mdev -> next ) ; if ( ! parent -> mdev_driver -> get_available ) { atomic_inc ( & parent -> available_instances ) ; } mutex_unlock ( & mdev_list_lock ) ; kobject_put ( & mdev -> type -> kobj ) ; dev_dbg ( & mdev -> dev , "MDEV: destroying\n" ) ; } 